import { readFileSync, writeFileSync, mkdirSync, renameSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = dirname(fileURLToPath(import.meta.url));
const dataPath = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const styles = readFileSync(join(root, 'public', 'styles.css'));

function loadBooks() {
  try {
    const books = JSON.parse(readFileSync(dataPath, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function saveBooks(books) {
  mkdirSync(dirname(dataPath), { recursive: true });
  const temp = `${dataPath}.${randomUUID()}.tmp`;
  writeFileSync(temp, JSON.stringify(books, null, 2) + '\n', { mode: 0o600 });
  renameSync(temp, dataPath);
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[char]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} · Bookkeep</title><link rel="stylesheet" href="/styles.css"></head>
<body><div class="site"><header class="site-header"><a class="brand" href="/" aria-label="Bookkeep home"><span class="brand-icon">B.</span><span>bookkeep</span></a><span class="header-note">A little space for your reading life</span></header>
<main>${content}</main><footer>Keep the good stories close. <span>✳</span></footer></div></body></html>`;
}

function send(res, status, body, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
}

function redirect(res, path) {
  res.writeHead(303, { Location: path });
  res.end();
}

function bookCard(book) {
  const url = `/books/${encodeURIComponent(book.id)}`;
  return `<article class="book-card"><div class="book-card-main"><span class="book-monogram" aria-hidden="true">${escapeHtml(book.title.trim().charAt(0).toUpperCase())}</span><div class="book-info"><a class="book-title" href="${url}">${escapeHtml(book.title)}</a><p>by ${escapeHtml(book.author)}</p></div></div><div class="book-card-end">${book.status === 'finished' ? '<span class="badge finished">Finished</span>' : `<form method="post" action="${url}/finish"><button class="text-button" type="submit" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark finished <span aria-hidden="true">↗</span></button></form>`}</div></article>`;
}

function shelf(heading, subtitle, books, emptyMessage) {
  return `<section class="shelf"><div class="shelf-heading"><div><h2>${heading}</h2><p>${subtitle}</p></div><span class="count">${books.length.toString().padStart(2, '0')}</span></div>${books.length ? `<div class="book-list">${books.map(bookCard).join('')}</div>` : `<p class="empty">${emptyMessage}</p>`}</section>`;
}

function home(books, error = '', values = {}) {
  const reading = books.filter(book => book.status === 'reading');
  const finished = books.filter(book => book.status === 'finished');
  return page('Your library', `<div class="hero"><div><div class="eyebrow"><span class="eyebrow-line"></span> YOUR PERSONAL LIBRARY</div><h1>Every book has<br><em>a story.</em></h1><p>A simple home for the books you’re reading, the ones you’ve loved, and the thoughts worth keeping.</p></div><div class="hero-art" aria-hidden="true"><span class="sparkle">✳</span><div class="art-book art-one"></div><div class="art-book art-two"></div><div class="art-book art-three"></div><span class="art-label">THE READING<br>COLLECTION</span></div></div>
<div class="library-layout"><div class="shelves">${shelf('Currently reading', 'The stories you’re in the middle of.', reading, 'Nothing on this shelf yet. Add a book to get started.')}${shelf('Finished', 'Good books stay with us.', finished, 'Finished books will find a home here.')}</div>
<aside class="add-panel" id="add-book"><div class="panel-icon">＋</div><span class="eyebrow">GROW YOUR SHELF</span><h2>Add a book</h2><p>What are you reading next? Give it a place here.</p>${error ? `<p class="form-error" role="alert">${escapeHtml(error)}</p>` : ''}<form method="post" action="/books"><label for="title">Book title <span>*</span></label><input id="title" name="title" required maxlength="200" placeholder="e.g. The Secret History" value="${escapeHtml(values.title || '')}"><label for="author">Author <span>*</span></label><input id="author" name="author" required maxlength="200" placeholder="e.g. Donna Tartt" value="${escapeHtml(values.author || '')}"><label for="notes">Your notes <small>OPTIONAL</small></label><textarea id="notes" name="notes" maxlength="10000" rows="5" placeholder="A thought, a quote, a reason you picked it up...">${escapeHtml(values.notes || '')}</textarea><button class="primary-button" type="submit">Add to my books <span aria-hidden="true">↗</span></button></form><p class="panel-footnote">✳ &nbsp;The best stories are worth remembering.</p></aside></div>`);
}

function detail(book) {
  const url = `/books/${encodeURIComponent(book.id)}`;
  return page(book.title, `<div class="detail"><a class="back-link" href="/">← &nbsp; Back to your library</a><div class="detail-paper"><div class="detail-top"><span class="eyebrow">FROM YOUR COLLECTION</span><span class="badge ${book.status === 'finished' ? 'finished' : 'reading'}">${book.status === 'finished' ? 'Finished' : 'Currently reading'}</span></div><div class="detail-body"><div class="detail-monogram" aria-hidden="true">${escapeHtml(book.title.trim().charAt(0).toUpperCase())}</div><div><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p></div></div><div class="notes-section"><span class="eyebrow">YOUR NOTES</span><div class="notes">${book.notes ? escapeHtml(book.notes) : '<span class="no-notes">No notes for this book yet.</span>'}</div></div><div class="detail-actions">${book.status === 'reading' ? `<form method="post" action="${url}/finish"><button class="primary-button" type="submit">Mark as finished <span aria-hidden="true">↗</span></button></form>` : '<span class="finished-note">✳ &nbsp;Another story for the shelf.</span>'}<span class="share-hint">Share this page by copying its link.</span></div></div></div>`);
}

async function readForm(req) {
  if (!(req.headers['content-type'] || '').startsWith('application/x-www-form-urlencoded')) throw new Error('Expected a form submission.');
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 30000) throw new Error('Form is too large.');
  }
  return new URLSearchParams(body);
}

export function createServer() {
  return http.createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && path === '/styles.css') return send(res, 200, styles, 'text/css; charset=utf-8');
      if (req.method === 'GET' && path === '/') return send(res, 200, home(loadBooks()));
      if (req.method === 'POST' && path === '/books') {
        const form = await readForm(req);
        const values = { title: (form.get('title') || '').trim(), author: (form.get('author') || '').trim(), notes: (form.get('notes') || '').trim() };
        const books = loadBooks();
        if (!values.title || !values.author || values.title.length > 200 || values.author.length > 200 || values.notes.length > 10000) {
          return send(res, 400, home(books, 'Please enter a title and author (up to 200 characters each) and notes up to 10,000 characters.', values));
        }
        const book = { id: randomUUID(), ...values, status: 'reading' };
        saveBooks([book, ...books]);
        return redirect(res, `/books/${book.id}`);
      }
      const finish = path.match(/^\/books\/([0-9a-f-]{36})\/finish$/);
      if (req.method === 'POST' && finish) {
        await readForm(req);
        const books = loadBooks();
        const book = books.find(item => item.id === finish[1]);
        if (!book) return send(res, 404, page('Not found', '<div class="not-found"><h1>Book not found.</h1><a href="/">Return to your library →</a></div>'));
        book.status = 'finished';
        saveBooks(books);
        return redirect(res, `/books/${book.id}`);
      }
      const match = path.match(/^\/books\/([0-9a-f-]{36})$/);
      if (req.method === 'GET' && match) {
        const book = loadBooks().find(item => item.id === match[1]);
        if (book) return send(res, 200, detail(book));
      }
      send(res, 404, page('Not found', '<div class="not-found"><h1>Page not found.</h1><a href="/">Return to your library →</a></div>'));
    } catch (error) {
      if (error.message === 'Expected a form submission.' || error.message === 'Form is too large.') return send(res, 400, page('Invalid form', `<div class="not-found"><h1>${escapeHtml(error.message)}</h1><a href="/">Return to your library →</a></div>`));
