      send(res, 500, page('Server error', '<div class="not-found"><h1>Something went wrong.</h1><p>Please check the books file and try again.</p><a href="/">Return to your library →</a></div>'));
    }
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT) || 3000;
