import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const directory = mkdtempSync(join(tmpdir(), 'bookkeep-test-'));
process.env.BOOKS_FILE = join(directory, 'books.json');
const { createServer } = await import('./server.js');

async function serve(server, callback) {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  try {
    return await callback(`http://127.0.0.1:${server.address().port}`);
  } finally {
    await new Promise(resolve => server.close(resolve));
  }
}

describe('book library', () => {
  it('adds a book, serves a shareable detail page, persists across server restarts, and finishes it', async () => {
    let location;
    await serve(createServer(), async base => {
      const empty = await fetch(base);
      expect(await empty.text()).toContain('Nothing on this shelf yet');
      const response = await fetch(`${base}/books`, {
        method: 'POST', redirect: 'manual',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ title: 'The & <Book>', author: 'A. Writer', notes: 'Remember <this>\nGreat read.' })
      });
      expect(response.status).toBe(303);
      location = response.headers.get('location');
      expect(location).toMatch(/^\/books\/[0-9a-f-]{36}$/);
      const detail = await fetch(base + location);
      expect(detail.status).toBe(200);
      const html = await detail.text();
      expect(html).toContain('The &amp; &lt;Book&gt;');
      expect(html).toContain('Remember &lt;this&gt;');
      expect(html).not.toContain('Remember <this>');
    });
    expect(JSON.parse(readFileSync(process.env.BOOKS_FILE, 'utf8'))).toHaveLength(1);
    await serve(createServer(), async base => {
      const home = await (await fetch(base)).text();
      expect(home).toContain('The &amp; &lt;Book&gt;');
      const finished = await fetch(`${base}${location}/finish`, { method: 'POST', redirect: 'manual', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: '' });
      expect(finished.status).toBe(303);
      expect((await (await fetch(base + location)).text())).toContain('Another story for the shelf.');
      expect((await (await fetch(base)).text())).toContain('Good books stay with us.');
      expect((await fetch(`${base}/books/00000000-0000-0000-0000-000000000000`)).status).toBe(404);
    });
    expect(JSON.parse(readFileSync(process.env.BOOKS_FILE, 'utf8'))[0].status).toBe('finished');
    rmSync(directory, { recursive: true, force: true });
  });

  it('rejects missing required fields without saving them', async () => {
    await serve(createServer(), async base => {
      const response = await fetch(`${base}/books`, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: 'title=Untitled' });
      expect(response.status).toBe(400);
      expect(await response.text()).toContain('Please enter a title and author');
    });
  });
});
"}

