      const finished = await fetch(`${base}${location}/finish`, { method: 'POST', redirect: 'manual', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: '' });
      expect(finished.status).toBe(303);
      expect((await (await fetch(base + location)).text())).toContain('Another story for the shelf.');
      expect((await (await fetch(base)).text())).toContain('Good books stay with us.');
      expect((await fetch(`${base}/books/00000000-0000-0000-0000-000000000000`)).status).toBe(404);
    });
    expect(JSON.parse(readFileSync(process.env.BOOKS_FILE, 'utf8'))[0].status).toBe('finished');
    rmSync(directory, { recursive: true, force: true });
  });

  it('rejects missing required fields without saving them', async () => {
    await serve(createServer(), async base => {
      const response = await fetch(`${base}/books`, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: 'title=Untitled' });
      expect(response.status).toBe(400);
      expect(await response.text()).toContain('Please enter a title and author');
    });
  });
